package org.example

fun String.esPalindromoSimple(): Boolean {

    if (!this.isNullOrBlank()) {

        var frase = this.lowercase().replace(" ","")
        var fraseInvertida = frase.reversed().lowercase().replace(" ","")
        return frase == fraseInvertida

    }
    return false
}


